head.script:
/* =========================================================================
 * WAEA-891 검증용 _fix 샘플 (버튼 클릭형)
 * 핫픽스: 2026_0602_hotfix_WAEA_891_v2.js (기준 REL_6_0_0_1485B_20260226_161523)
 *
 * 신규 API 검증:
 *   gridView1.setCellImageSrc(rowIndex, columnInfo, imageSrc)
 *   gridView1.getCellImageSrc(rowIndex, columnInfo)
 *   gridView1.removeCellImageSrc(rowIndex, columnInfo)
 *
 * 이미지: icon_D.gif(컬럼 기본) / icon_C.gif, icon_U.gif(변경 테스트용) — 같은 폴더 존재
 * 각 버튼 클릭 후 하단 로그(txa_log)와 그리드 화면으로 결과 확인.
 * ========================================================================= */

// --- 로그 helper (textarea + console 동시 출력) ---
scwin.log = function (msg, obj) {
    var line = msg + (obj !== undefined ? " " + JSON.stringify(obj) : "");
    console.log("[WAEA-891]", msg, (obj !== undefined ? obj : ""));
    try { txa_log.setValue((txa_log.getValue() || "") + line + "\n"); } catch (e) {}
};
scwin.clearLog = function () { try { txa_log.setValue(""); } catch (e) {} };

// --- 상태 조회 (원본 샘플 헬퍼 유지) ---
scwin.getCellImageStates = function () {
    var states = [], gridId = gridView1.id;
    for (var r = 0; r < dlt_task.getTotalRow(); r++) {
        var cell = document.getElementById(gridId + "_cell_" + r + "_0");
        var img = cell ? cell.querySelector("img") : null;
        var stored = gridView1.getCellImageSrc(r, "status");
        states.push({ row: r, data: dlt_task.getCellData(r, "status"),
            stored: stored == null ? null : stored, src: img ? img.getAttribute("src") : null });
    }
    return states;
};
scwin.getEmbeddedImageStates = function () {
    var states = [], gridId = gridView1.id;
    for (var r = 0; r < dlt_task.getTotalRow(); r++) {
        var cell = document.getElementById(gridId + "_cell_" + r + "_1");
        var button = cell ? cell.querySelector(".w2grid_textImage_button") : null;
        var stored = gridView1.getCellImageSrc(r, "embedded");
        states.push({ row: r, data: dlt_task.getCellData(r, "embedded"),
            stored: stored == null ? null : stored,
            backgroundImage: button ? button.style.backgroundImage : null });
    }
    return states;
};

/* ===================== 검증 케이스 버튼 ===================== */

// ① 특정 셀만 변경: 0행 status → icon_C.gif (1·2행은 기본 icon_D.gif 유지 기대)
scwin.case1 = function () {
    var ret = gridView1.setCellImageSrc(0, "status", "gridView_cellImageSrc_WAEA-891_WSQ-6302_icon_C.gif");
    scwin.log("① setCellImageSrc(0,'status','icon_C.gif') 반환=", ret);
    scwin.log("   status 상태=", scwin.getCellImageStates());
};

// ② 조회: getCellImageSrc(0,'status')
scwin.case2 = function () {
    scwin.log("② getCellImageSrc(0,'status') =", gridView1.getCellImageSrc(0, "status"));
};

// ③ 빈 문자열 = 이미지 숨김: 1행 status → ""
scwin.case3 = function () {
    var ret = gridView1.setCellImageSrc(1, "status", "");
    scwin.log("③ setCellImageSrc(1,'status','') 반환=", ret);
    scwin.log("   status 상태=", scwin.getCellImageStates());
};

// ④ 삭제 = 컬럼 기본 복귀: removeCellImageSrc(0,'status')
scwin.case4 = function () {
    var ret = gridView1.removeCellImageSrc(0, "status");
    scwin.log("④ removeCellImageSrc(0,'status') 반환=", ret);
    scwin.log("   status 상태=", scwin.getCellImageStates());
};

// ⑤ null 지정 = 삭제와 동일: setCellImageSrc(2,'status', null)
scwin.case5 = function () {
    var ret = gridView1.setCellImageSrc(2, "status", null);
    scwin.log("⑤ setCellImageSrc(2,'status',null) 반환=", ret);
    scwin.log("   status 상태=", scwin.getCellImageStates());
};

// ⑥ embeddedInput 즉시 갱신(v2 보강): 0행 embedded → icon_U.gif
scwin.case6 = function () {
    var ret = gridView1.setCellImageSrc(0, "embedded", "gridView_cellImageSrc_WAEA-891_WSQ-6302_icon_U.gif");
    scwin.log("⑥ setCellImageSrc(0,'embedded','icon_U.gif') 반환=", ret);
    scwin.log("   embedded 상태=", scwin.getEmbeddedImageStates());
};

// ⑦ 행 삽입/이동 후 이미지 유지: 2행에 set 후 맨 위에 행 삽입
scwin.case7 = function () {
    gridView1.setCellImageSrc(2, "status", "gridView_cellImageSrc_WAEA-891_WSQ-6302_icon_C.gif");
    scwin.log("⑦ 삽입 전 status 상태=", scwin.getCellImageStates());
    dlt_task.insertRow(0, { status: "New", embedded: "New", name: "Inserted" });
    scwin.log("⑦ 0행 삽입 후 status 상태=", scwin.getCellImageStates());
    scwin.log("   → 'icon_C.gif' 가 원래 데이터(Done) 행을 따라갔는지 확인");
};

// 상태만 출력
scwin.showStatus   = function () { scwin.log("status 상태=", scwin.getCellImageStates()); };
scwin.showEmbedded = function () { scwin.log("embedded 상태=", scwin.getEmbeddedImageStates()); };

// 초기화: 페이지 리로드
scwin.resetAll = function () { location.reload(); };

scwin.onpageload = function () {
    scwin.log("WAEA-891 _fix 로드 완료. ①~⑦ 버튼을 순서대로 눌러 확인하세요.");
    scwin.log("초기 status 상태=", scwin.getCellImageStates());
};
